    public function run(): void
    {
        AuditLog::withoutRecording(function (): void {
            FinancialSupportMonth::withTrashed()->forceDelete();
            FinancialSupportTransfer::withTrashed()->forceDelete();

            $now = now();

            foreach (self::months() as $monthRow) {
                FinancialSupportMonth::query()->create($monthRow);
            }

            $payload = [];
            foreach (self::transfers() as $row) {
                $payload[] = [
                    'support_year' => 2026,
                    'support_month' => $row[0],
                    'equipment_type' => $row[1],
                    'equipment_code' => $row[2],
                    'amount' => $row[3],
                    'beneficiary_name' => $row[4],
                    'fault_type' => $row[5],
                    'branch' => $row[6],
                    'case_status' => $row[7],
                    'po_number' => $row[8],
                    'transfer_stage' => $row[9],
                    'transfer_date' => $row[10],
                    'supply_date' => $row[11],
                    'repair_date' => $row[12],
                    'repair_status' => $row[13],
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            }

            foreach (array_chunk($payload, 50) as $chunk) {
                FinancialSupportTransfer::query()->insert($chunk);
            }
        });

        DashboardService::clearCache();
    }
